head.script:
scwin.vScrenID = "ULDFIL54000.xml";

scwin.onpageload = async function() {

    scwin.selectListedFee(true);

};

/**
 * 상장수수료 조회
 * @Desc : 
 */
scwin.selectListedFee = async function (isFirst) {

     if(isFirst) {

        dma_SearchReq.set("integUsrId", "ss2020_08") //userId 임시 let userID = $c.stf.getUserInfo("id"); 
        dma_SearchReq.set("corpUserTpCd",  61) //시장구분코드
        dma_SearchReq.set("page", 1);//현재페이지 초기화
        dma_SearchReq.set("size", 10);//페이지당 데이터 개수 (기본값: 10, 최대: 100)

    }
    grd_listedFee.initGrid();

    const sbmOptions = {
        id : "sbm_ListedFeeRes",
        action : "/api/listing/listinvstg/listfee/select-list",
        method : "get",
        ref : "dma_SearchReq",
        target : "dlt_ListedFeeRes=body.content,dma_pageRes=body",
        gridview : "grd_listedFee",
        isProcessMsg : false
    };
    let res = await await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success === true) {
        const resBody = res.responseJSON.body;
        //dlt_ListedFeeRes.setJSON(resBody.content);
        if (isFirst) {
            //페이지네이션 생성
            const totalCnt = $c.num.ceil(resBody.totalCount / resBody.size);
            tbx_totalCount.setValue(resBody.totalCount)
            pageList1.setCount(totalCnt);
        } else {
            pageList1.setSelectedIndex(resBody.page);
        }
    }

};

