    grd_listedFee.refresh();
};

//inputType에 따라 미리 property 를 정의한다.
scwin.inputTypeCustomObj = {
    //button: { inputType: "button", value: "인쇄", options : { label: "인쇄" } }
     button1: { inputType: "button", value: "인쇄"}
    ,button2: { inputType: "button", value: "수정요청"}
    ,button3: { inputType: "button", value: "제출"}
};

scwin.customFormatter1 = function (data, formattedData, rowIndex, columnIndex) {
	let inputType = dlt_ListedFeeRes.getCellData(rowIndex, "listProcsStatCd");
    let listProcsStatNm = dlt_ListedFeeRes.getCellData(rowIndex, "listProcsStatNm");

    if(columnIndex === 5 ) { //상태 컬럼
        if (inputType === '33' || inputType === '36' ) {
            const obj = scwin.inputTypeCustomObj['button1'];
            grd_listedFee.setCellInputType(rowIndex, columnIndex, obj);
            data = obj.value;
        } else {
            data = listProcsStatNm;
        }
    } 

    //console.log("data === ", data);

    return data;    
};

scwin.customFormatter2 = function (data, formattedData, rowIndex, columnIndex) {
	let inputType = dlt_ListedFeeRes.getCellData(rowIndex, "listProcsStatCd");

    if (columnIndex === 6 ) { //비고 컬럼

        if (inputType === '33' || inputType === '36' ) {
            const obj = scwin.inputTypeCustomObj['button2'];
            grd_listedFee.setCellInputType(rowIndex, columnIndex, obj);
            data = obj.value;
        } else if (inputType === '30' || inputType === '35' || inputType === '37' ) {
            const obj = scwin.inputTypeCustomObj['button3'];
            grd_listedFee.setCellInputType(rowIndex, columnIndex, obj);
            data = obj.value;
        }
    } 
    //console.log("data === ", data);

    return data;    
};
